  iH = `เกมนี้วางจำหน่ายได้พักใหญ่แล้ว และทีมงานก็ผ่านพ้นช่วงที่อุ้มลูกน้อยออกอวดชาวบ้านเป็นครั้งแรกมานาน แต่เนื่องจากเป็นพ่อแม่ที่น่ารัก ผู้พัฒนาเหล่านี้จึงดูแลเอาใจใส่ลูกน้อยด้วยดีเสมอมา เกมนี้จึงยังคงมีเนื้อหาใหม่ ๆ มาตลอดเวลาที่วางจำหน่ายหลายปีจนกระทั่งถึงวันนี้`,
  aH = `มีบางเกมที่คุณเล่นคนเดียวแล้วไม่สนุกเอาเสียเลย บางทีคุณอาจต้องมีเพื่อนไว้คอยเฝ้าระวังหลังให้คุณ บางทีคุณอาจต้องมีเพื่อนไว้ให้คุณแอบแทงหลังได้ ไม่ว่าแบบไหนก็ตาม ความสนุกกำลังรอให้คุณรวบรวมสมัครพรรคพวกมาร่วมเล่นเกมนี้ด้วยกัน`,
  oH = `สไตล์ภาพไม่ได้มุ่งหมายให้มีความเที่ยงตรงตามแบบภาพกราฟิกในโลกแห่งความเป็นจริง (แม้ว่าจะเป็นเป้าหมายอันสูงส่งในตัวเองก็ตาม)... แต่แสดงถึงรูปลักษณ์และความรู้สึกอันโดดเด่นที่แทรกซึมไปทั่วทั้งเกม`,
  sH = `ผู้ออกแบบเกมนี้ยืนอยู่แถวหน้าของการทดสอบความสร้างสรรค์ โดยนำเสนอมุมมองที่แปลกใหม่และสิ่งที่สร้างความประหลาดใจจนสมองตามไม่ทัน เกมนี้เปี่ยมด้วยความปลื้มปีติ แรงบันดาลใจ และความบันเทิงที่มาพร้อมความใหม่เอี่ยมที่ไม่เคยเล่นมาก่อน`,
  cH = `นี่เป็นเกมที่ให้รางวัลความอึดและไม่เหมาะสำหรับคนใจเสาะ แต่เป็นเกมที่ยากที่สุดที่เราชื่นชอบ`,
  lH = `เพลงดีที่โลกลืมนี้สมควรได้รับการยกย่องว่ามีโน้ตเพลงยอดเยี่ยม จัดเป็นเพลงประกอบที่โดดเด่นที่สุด! `,
  uH = `บางวัน ต้องเกมแบบเน้นคำบรรยายเท่านั้นถึงจะโดนใจคุณ และเกมนี้เต็มไปด้วยบทบรรยายที่จับจิตจับใจเหมือนละครทีวีทั่วไป และผ่านการปรุงแต่งมาอย่างดีไม่ผิดกับบทภาพยนตร์โทรทัศน์ชั้นเยี่ยม ไชโย - เกมนี้ทำให้เรารู้สึกรู้สาได้อีก!`,
  dH = `เกมนี้เหมือนไอศกรีมในวันอากาศร้อน เนื้อนุ่มลิ้น ชิมแล้วสบายใจ ละลายความเครียดจนเกลี้ยง เกมนี้จะช่วยให้คุณมีจิตสุขใจสงบ`,
  fH = `ต้องการเปลี่ยนชื่อเกมที่คุณเสนอเข้าชิงรางวัลหรือ?`,
  pH = `คุณมีสิทธิ์เสนอชื่อเข้าชิงรางวัลในแต่ละหมวดได้เพียงเกมเดียวเท่านั้น และคุณได้เสนอชื่อเกม %1$s ในหมวดนี้ไปแล้ว คุณต้องการที่จะเสนอชื่อเกม %2$s แทนใช่หรือไม่?`,
  mH = `โหวต`,
  hH = `โหวตแล้ว`,
