  yH = `ดูเหมือนว่าบัญชีของคุณเป็นบัญชีแบบจำกัดสิทธิ์ ดังนั้นคุณต้องซื้อสินค้าบน Steam ครบ 5 ดอลลาร์สหรัฐ จึงจะมีสิทธิ์เข้าร่วมงานรางวัล Steam ได้ ทั้งนี้เพื่อไม่ให้ผิดกฎการเสนอชื่อเกม หากต้องการข้อมูลเพิ่มเติม %1$s`,
  bH = `ดูเหมือนว่าบัญชีของคุณเป็นบัญชีแบบจำกัดสิทธิ์ ดังนั้นคุณต้องซื้อสินค้าบน Steam ครบ 5 ดอลลาร์สหรัฐ จึงจะมีสิทธิ์เข้าร่วมงานรางวัล Steam ได้ ทั้งนี้เพื่อไม่ให้ผิดกฎการโหวต หากต้องการข้อมูลเพิ่มเติม %1$s`,
