  GH = `สไตล์ภาพดีเด่น`,
  KH = `เกมเพลย์สร้างสรรค์ยอดเยี่ยม`,
  qH = `เกมที่คุณเล่นได้ห่วยแตกที่สุด`,
  JH = `เพลงประกอบยอดเยี่ยม`,
  YH = `เกมเน้นการเล่าเรื่องดีเด่น`,
  XH = `นั่งลงแล้วผ่อนคลาย`,
  ZH = `เกมพกพายอดเยี่ยม`,
  QH = `บางทีอาจเป็นเพราะมีเกมเพลย์ที่ชวนดื่มด่ำ หรือเรื่องราวที่จับจิตจับใจ... ตัวละครที่ปั้นแต่งไว้เป็นอย่างดี การออกแบบที่ไร้ที่ติ หรือโหมดผู้เล่นหลายคนที่เล่นได้ไม่เบื่อ ไม่ว่าด้วยเหตุผลใดก็ตาม เกมที่ชนะรางวัลเกมแห่งปีประจำปีนี้จะก้าวขึ้นแท่นเกมคลาสสิกทันที`,
  $H = `เกม VR แห่งปีไม่ได้ซ่อนตัวอยู่หลังหน้ากากความเป็นจริงตามปกติ แต่ยกระดับความเป็นจริงโดยใช้ประโยชน์จากสื่อ VR และพุ่งทะยานผ่านขอบกั้นโลกเสมือนจริง`,
  eU = `เกมนี้วางจำหน่ายได้พักใหญ่แล้ว และทีมงานก็ผ่านพ้นช่วงที่อุ้มลูกน้อยออกอวดชาวบ้านเป็นครั้งแรกมานาน แต่เนื่องจากเป็นพ่อแม่ที่น่ารัก ผู้พัฒนาเหล่านี้จึงดูแลเอาใจใส่ลูกน้อยด้วยดีเสมอมา เกมนี้จึงยังคงมีเนื้อหาใหม่ ๆ มาตลอดเวลาที่วางจำหน่ายหลายปีจนกระทั่งถึงวันนี้`,
  tU = `มีบางเกมที่คุณเล่นคนเดียวแล้วไม่สนุกเอาเสียเลย บางทีคุณอาจต้องมีเพื่อนไว้คอยเฝ้าระวังหลังให้คุณ หรือบางทีคุณอาจต้องมีเพื่อนไว้ให้คุณแอบแทงข้างหลังได้ ไม่ว่าแบบไหนก็ตาม ความสนุกกำลังรอให้คุณรวบรวมสมัครพรรคพวกมาร่วมเล่นเกมนี้ด้วยกัน`,
  nU = `สไตล์ภาพไม่ได้มุ่งหมายให้มีความเที่ยงตรงตามแบบภาพกราฟิกในโลกแห่งความเป็นจริง (แม้ว่าจะเป็นเป้าหมายอันสูงส่งในตัวเองก็ตาม)... แต่แสดงถึงรูปลักษณ์และความรู้สึกอันโดดเด่นที่แทรกซึมไปทั่วทั้งเกม`,
  rU = `ผู้ออกแบบเกมนี้ยืนอยู่แถวหน้าของการทดสอบความสร้างสรรค์ โดยนำเสนอมุมมองที่แปลกใหม่และสิ่งที่สร้างความประหลาดใจจนสมองตามไม่ทัน เกมนี้เปี่ยมด้วยความปลื้มปีติ แรงบันดาลใจ และความบันเทิงที่มาพร้อมความใหม่เอี่ยมที่ไม่เคยเล่นมาก่อน`,
  iU = `นี่เป็นเกมที่ให้รางวัลความอึดและไม่เหมาะสำหรับคนใจเสาะ แต่เป็นเกมที่ยากที่สุดที่เราชื่นชอบ`,
  aU = `เพลงดีที่โลกลืมนี้สมควรได้รับการยกย่องว่ามีโน้ตเพลงยอดเยี่ยม จัดเป็นเพลงประกอบที่โดดเด่นที่สุด! `,
