  nme = `ความแตกต่างในแผนภูมิ (เช่น ระหว่าง %1$s และ %2$s FPS) อาจเกิดจาก VSync ที่ทำการซิงโครไนซ์การส่งเฟรมกับอัตรารีเฟรชของจอแสดงผลเพื่อป้องกันภาพฉีกขาด ซึ่งอาจทำให้ตัวอย่างข้อมูลกระจุกตัวอยู่ที่ %1$s และ %2$s FPS แม้ว่าอัตราเฟรมเฉลี่ยของเกมจะอยู่ระหว่างค่าเหล่านั้นก็ตาม นี่เป็นพฤติกรรมปกติของ VSync และอาจส่งผลต่อจังหวะของเฟรม แต่ไม่ได้ทำให้เกิดอาการภาพกระตุกที่สังเกตเห็นได้ชัดเสมอไป`,
